/**
 * 同步状态徽章
 * 显示模块的同步状态：已同步 / 未同步 / 同步中 / 同步失败
 */

import { CheckCircle2, AlertCircle, Loader2, CloudOff } from 'lucide-react';
import type { SyncStatusMap } from '@/hooks/useGithubSync';

interface SyncStatusBadgeProps {
  status: 'synced' | 'dirty' | 'syncing' | 'error';
  showText?: boolean;
  size?: 'sm' | 'md';
}

export default function SyncStatusBadge({
  status,
  showText = true,
  size = 'sm',
}: SyncStatusBadgeProps) {
  const iconSize = size === 'sm' ? 'size-3.5' : 'size-4';

  const config = {
    synced: {
      icon: CheckCircle2,
      text: 'Synced',
      className: 'text-emerald-500',
      bgClass: 'bg-emerald-500/10 border-emerald-500/20',
    },
    dirty: {
      icon: AlertCircle,
      text: 'Unsynced',
      className: 'text-amber-500',
      bgClass: 'bg-amber-500/10 border-amber-500/20',
    },
    syncing: {
      icon: Loader2,
      text: 'Syncing...',
      className: 'text-primary',
      bgClass: 'bg-primary/10 border-primary/20',
    },
    error: {
      icon: CloudOff,
      text: 'Sync Error',
      className: 'text-destructive',
      bgClass: 'bg-destructive/10 border-destructive/20',
    },
  }[status];

  const Icon = config.icon;

  return (
    <div
      className={`inline-flex items-center gap-1.5 px-2 py-1 rounded-md border ${config.bgClass} ${config.className}`}
    >
      <Icon className={`${iconSize} ${status === 'syncing' ? 'animate-spin' : ''}`} />
      {showText && (
        <span className="text-xs font-medium">{config.text}</span>
      )}
    </div>
  );
}
